var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Pemeriksaan baca-saja singkat untuk memastikan printer siap memulai pencetakan.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Periksa ulang`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Memeriksa...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Siap mencetak`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Belum siap mencetak`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`Printer tidak dapat dijangkau`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper siap`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper belum siap (status: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada pencetakan yang berlangsung`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Pencetakan sudah berjalan (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Semua sumbu sudah di-homing`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Sumbu belum di-homing (`},{t:4,k:`axes`},{t:3,v:`); memulai pencetakan biasanya melakukan homing terlebih dahulu`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Panduan`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Panduan pemeriksaan pra-cetak`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Tutup`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu pemeriksaan pra-cetak?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Tinjauan baca-saja apakah printer siap memulai: tidak pernah menggerakkan atau mengubah apa pun, hanya melaporkan. Penghambat keras membuat hasilnya merah; peringatan memberi tahu tetapi tidak menghambat.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa yang diperiksa`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Klipper siap (tidak mati atau dalam galat), tidak ada pencetakan yang sedang berjalan, dan apakah sumbu sudah di-homing (informatif, karena memulai pencetakan biasanya melakukan homing terlebih dahulu).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosarium`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Status Klipper`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Status Klipper sendiri - 'ready' (siap) berarti terhubung dan diam; 'shutdown' (mati) atau 'error' (galat) berarti tidak dapat mencetak hingga dibersihkan.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Homing`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Menggerakkan setiap sumbu ke endstop-nya agar printer tahu di mana toolhead berada. Sebagian besar rutinitas mulai-cetak melakukan homing secara otomatis.`}}}}}}};export{e as default};